/**
 * Função de normalização para ignorar acentos, espaços duplos e maiúsculas
 */
export function normalizeFestivalKey(key) {
    if (!key) return '';
    return key
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '') // Remove acentos
        .toLowerCase()
        .replace(/[^a-z0-9]/g, ''); // Mantém apenas letras e números
}

